CREATE SCHEMA IF NOT EXISTS wax;
CREATE TABLE wax.users (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, email_verified boolean NOT NULL DEFAULT false, image text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX users_email_lower_idx ON wax.users(lower(email));
CREATE TABLE wax.sessions (id text PRIMARY KEY, expires_at timestamptz NOT NULL, token text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ip_address text, user_agent text, user_id text NOT NULL REFERENCES wax.users(id) ON DELETE CASCADE);
CREATE INDEX sessions_user_idx ON wax.sessions(user_id);
CREATE TABLE wax.accounts (id text PRIMARY KEY, account_id text NOT NULL, provider_id text NOT NULL, user_id text NOT NULL REFERENCES wax.users(id) ON DELETE CASCADE, access_token text, refresh_token text, id_token text, access_token_expires_at timestamptz, refresh_token_expires_at timestamptz, scope text, password text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider_id,account_id));
CREATE INDEX accounts_user_idx ON wax.accounts(user_id);
CREATE TABLE wax.verifications (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX verifications_identifier_idx ON wax.verifications(identifier);
CREATE TABLE wax.rate_limits (id text PRIMARY KEY, key text NOT NULL UNIQUE, count integer NOT NULL, last_request bigint NOT NULL);
CREATE TABLE wax.collectors (id text PRIMARY KEY REFERENCES wax.users(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wax.app_owner (singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton), user_id text NOT NULL UNIQUE REFERENCES wax.collectors(id));
CREATE TABLE wax.invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), token_hash text NOT NULL UNIQUE, email text NOT NULL, kind text NOT NULL CHECK(kind IN ('owner','collector')), created_by text REFERENCES wax.collectors(id), created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, revoked_at timestamptz, consumed_at timestamptz, redeemed_user_id text REFERENCES wax.users(id));
CREATE INDEX invitations_email_idx ON wax.invitations(lower(email));
CREATE UNIQUE INDEX one_bootstrap_invite ON wax.invitations(kind) WHERE kind='owner';
CREATE TABLE wax.registration_limits (key text PRIMARY KEY, count integer NOT NULL, window_start timestamptz NOT NULL);
CREATE TABLE wax.releases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), discogs_id bigint UNIQUE, metadata jsonb NOT NULL, fetched_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wax.copies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id text NOT NULL REFERENCES wax.collectors(id) ON DELETE CASCADE, release_id uuid NOT NULL REFERENCES wax.releases(id), metadata jsonb NOT NULL, media_condition text NOT NULL DEFAULT 'Not graded' CHECK(media_condition IN ('M','NM','VG+','VG','G+','G','F','P','Not graded')), sleeve_condition text NOT NULL DEFAULT 'Not graded' CHECK(sleeve_condition IN ('M','NM','VG+','VG','G+','G','F','P','Not graded')), purchase_price numeric(12,2) CHECK(purchase_price>=0), currency char(3) NOT NULL DEFAULT 'USD', acquired_at date, notes text NOT NULL DEFAULT '', rating integer NOT NULL DEFAULT 0 CHECK(rating BETWEEN 0 AND 5), location text NOT NULL DEFAULT '', intent text NOT NULL DEFAULT 'keep' CHECK(intent IN ('keep','trade','sell')), pressing_confirmed boolean NOT NULL DEFAULT false, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,owner_id));
CREATE INDEX copies_owner_created_idx ON wax.copies(owner_id,created_at DESC);
CREATE INDEX copies_owner_release_idx ON wax.copies(owner_id,release_id);
CREATE TABLE wax.crates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id text NOT NULL REFERENCES wax.collectors(id) ON DELETE CASCADE, name text NOT NULL, description text NOT NULL DEFAULT '', color text NOT NULL DEFAULT '#d85a2a', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,owner_id));
CREATE TABLE wax.crate_items (crate_id uuid NOT NULL, copy_id uuid NOT NULL, owner_id text NOT NULL, PRIMARY KEY(crate_id,copy_id), FOREIGN KEY(crate_id,owner_id) REFERENCES wax.crates(id,owner_id) ON DELETE CASCADE, FOREIGN KEY(copy_id,owner_id) REFERENCES wax.copies(id,owner_id) ON DELETE CASCADE);
CREATE TABLE wax.crate_shares (crate_id uuid NOT NULL REFERENCES wax.crates(id) ON DELETE CASCADE, recipient_id text NOT NULL REFERENCES wax.collectors(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(crate_id,recipient_id));
CREATE INDEX crate_shares_recipient_idx ON wax.crate_shares(recipient_id);
CREATE TABLE wax.listens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id text NOT NULL, copy_id uuid NOT NULL, played_at timestamptz NOT NULL DEFAULT now(), notes text NOT NULL DEFAULT '', FOREIGN KEY(copy_id,owner_id) REFERENCES wax.copies(id,owner_id) ON DELETE CASCADE);
CREATE INDEX listens_owner_played_idx ON wax.listens(owner_id,played_at DESC);
CREATE TABLE wax.mutation_requests (owner_id text NOT NULL REFERENCES wax.collectors(id) ON DELETE CASCADE, key text NOT NULL, request_hash text NOT NULL, result_id uuid, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(owner_id,key));
